  const searchable=$$('section[id]').filter(s=>s.querySelector('h2')).map(s=>({id:s.id,title:s.querySelector('h2').textContent,body:s.textContent.toLowerCase()}));
  function renderSearch(){const terms=searchInput.value.trim().toLowerCase().split(/\s+/).filter(Boolean); const matches=searchable.filter(s=>terms.every(t=>(s.title+' '+s.body).toLowerCase().includes(t)));results.innerHTML=matches.length?matches.map(s=>`<a role="listitem" class="search-result" href="#${s.id}"><span>${escape(s.title)}</span><small>→</small></a>`).join(''):'<p class="no-results">No matching sections. Try “Go”, “booking” or “latency”.</p>';$$('a',results).forEach(a=>a.addEventListener('click',()=>{previousFocus=null;searchDialog.close();const target=document.getElementById(a.hash.slice(1));if(target){target.tabIndex=-1;requestAnimationFrame(()=>target.focus({preventScroll:true}));}}));}
  function openSearch(){closeMenu();previousFocus=document.activeElement;searchInput.value='';renderSearch();searchDialog.showModal();searchInput.focus();}
  $('#searchButton').addEventListener('click',openSearch);$('#closeSearch').addEventListener('click',()=>searchDialog.close());searchInput.addEventListener('input',renderSearch);
  searchDialog.addEventListener('close',()=>previousFocus?.focus());searchDialog.addEventListener('click',e=>{if(e.target===searchDialog){const r=searchDialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)searchDialog.close();}});
  searchDialog.addEventListener('keydown',e=>{const links=$$('a',results),index=links.indexOf(document.activeElement);if(e.key==='ArrowDown'){e.preventDefault();links[(index+1)%links.length]?.focus();}if(e.key==='ArrowUp'){e.preventDefault();if(index<=0)searchInput.focus();else links[index-1]?.focus();}if(e.key==='Enter'&&document.activeElement===searchInput){e.preventDefault();links[0]?.click();}});
  document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(!searchDialog.open)openSearch();else searchDialog.close();}if(e.key==='Escape'&&!$('#mobileMenu').hidden){closeMenu();$('#menuButton').focus();}});
