  $$('a',menu).forEach(a=>a.addEventListener('click',closeMenu));document.addEventListener('click',e=>{if(!menu.hidden&&!menu.contains(e.target)&&!menuButton.contains(e.target))closeMenu();});
  // Active anchors are observed without continuous scroll handlers.
  const observer=new IntersectionObserver(entries=>{for(const entry of entries){if(!entry.isIntersecting)continue;const id=entry.target.id;const links=$$('.ref-link');if(links.some(a=>a.hash==='#'+id))links.forEach(a=>a.hash==='#'+id?a.setAttribute('aria-current','location'):a.removeAttribute('aria-current'));const mainId=['architectures','pipeline','roadmap'].includes(id)?id:(entry.target.closest('.reference-content')?'specifications':id);$$('.main-nav a').forEach(a=>a.hash==='#'+mainId?a.setAttribute('aria-current','location'):a.removeAttribute('aria-current'));}},{rootMargin:'-95px 0px -65% 0px'});$$('section[id]').forEach(s=>observer.observe(s));
  // Costs retain the original formula and exclusions; invalid input never creates negative or infinite totals.
  const calcFields=['callsDay','minsCall','voicePrice','carrierPrice'].map(id=>document.getElementById(id));
  const calcRoot=$('.calc');calcRoot.insertAdjacentHTML('beforeend','<div class="cost-breakdown" aria-hidden="true"><span id="voiceShare"></span></div><div class="cost-legend"><span id="voiceCost">Voice</span><span id="carrierCost">Carrier</span></div><p class="calc-error" id="calcError" role="status" hidden></p>');
  const money=v=>v.toLocaleString('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2});
  function calculate(){const invalid=calcFields.some(el=>el.validity.badInput||el.validity.rangeOverflow||Number(el.value)<0||!Number.isFinite(Number(el.value)));const values=calcFields.map(el=>Math.max(0,Number(el.value)||0));const minutes=values[0]*values[1]*30,voice=minutes*values[2],carrier=minutes*values[3],total=voice+carrier;const valid=!invalid&&Number.isFinite(total);$('#calcError').hidden=valid;$('#calcError').textContent='Enter finite, non-negative values within the displayed limits.';$('#calcTotal').textContent=valid?money(total):'—';$('#calcTotal').setAttribute('aria-live','polite');$('#calcDetails').textContent=valid?`${minutes.toLocaleString('en-US')} estimated minutes/month · voice ${money(voice)} + illustrative carrier ${money(carrier)}. Excludes delegated models, tool calls, taxes, phone numbers, recordings, storage, egress, payment costs, retries and platform overhead. Carrier rate is an editable example, not a quote.`:'The estimate will update when all values are valid.';$('#voiceCost').textContent=valid?'Voice '+money(voice):'Voice —';$('#carrierCost').textContent=valid?'Carrier '+money(carrier):'Carrier —';$('#voiceShare').style.width=(valid&&total>0?voice/total*100:0)+'%';}
  calcFields.forEach(el=>el.addEventListener('input',calculate));calculate();
